import{_ as n,a0 as p,w as o,s as r,I as s,x as t,a1 as l,A as a,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"Git 使用简介 | LCTT x X-CMD","titleTemplate":false,"description":"Git 使用简介 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Git 使用简介 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Git 使用简介 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180720 An Introduction to Using Git","title":"Git 使用简介","tag":"201809","desc":""},"relativePath":"201809/20180720 An Introduction to Using Git.md","filePath":"[post].md"}'),g={name:"201809/20180720 An Introduction to Using Git.md"};function u(h,i,b,k,m,c){const e=p("Link");return o(),r("div",null,[i[26]||(i[26]=s("h1",{id:"git-使用简介",tabindex:"-1"},[t("Git 使用简介 "),s("a",{class:"header-anchor",href:"#git-使用简介","aria-label":"Permalink to “Git 使用简介”"},"​")],-1)),i[27]||(i[27]=s("blockquote",null,[s("p",null,"我将向你介绍让 Git 的启动、运行，并和 GitHub 一起使用的基础知识。")],-1)),i[28]||(i[28]=s("p",null,[s("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/developer-3461405_1920.png?itok=6H3sYe80",alt:""})],-1)),i[29]||(i[29]=s("p",null,"如果你是一个开发者，那你应该熟悉许多开发工具。你已经花了多年时间来学习一种或者多种编程语言并打磨你的技巧。你可以熟练运用图形工具或者命令行工具开发。在你看来，没有任何事可以阻挡你。你的代码, 好像你的思想和你的手指一样，将会创建一个优雅的，完美评价的应用程序，并会风靡世界。",-1)),s("p",null,[i[2]||(i[2]=t("然而，如果你和其他人共同开发一个项目会发生什么呢？或者，你开发的应用程序变地越来越大，下一步你将如何去做？如果你想成功地和其他开发者合作，你定会想用一个分布式版本控制系统。使用这样一个系统，合作开发一个项目变得非常高效和可靠。这样的一个系统便是 ",-1)),l(e,{href:"https://git-scm.com/"},{default:a(()=>[...i[0]||(i[0]=[t("Git",-1)])]),_:1}),i[3]||(i[3]=t("。还有一个叫 ",-1)),l(e,{href:"https://github.com/"},{default:a(()=>[...i[1]||(i[1]=[t("GitHub",-1)])]),_:1}),i[4]||(i[4]=t(" 的方便的存储仓库，用来存储你的项目代码，这样你的团队可以检查和修改代码。",-1))]),i[30]||(i[30]=s("p",null,"我将向你介绍让 Git 的启动、运行，并和 GitHub 一起使用的基础知识，可以让你的应用程序的开发可以提升到一个新的水平。我将在 Ubuntu 18.04 上进行演示，因此如果您选择的发行版本不同，您只需要修改 Git 安装命令以适合你的发行版的软件包管理器。",-1)),i[31]||(i[31]=s("h3",{id:"git-和-github",tabindex:"-1"},[t("Git 和 GitHub "),s("a",{class:"header-anchor",href:"#git-和-github","aria-label":"Permalink to “Git 和 GitHub”"},"​")],-1)),s("p",null,[i[6]||(i[6]=t("第一件事就是创建一个免费的 GitHub 账号，打开 ",-1)),l(e,{href:"https://github.com/join?source=header-home"},{default:a(()=>[...i[5]||(i[5]=[t("GitHub 注册页面",-1)])]),_:1}),i[7]||(i[7]=t("，然后填上需要的信息。完成这个之后，你就注备好开始安装 Git 了（这两件事谁先谁后都可以）。",-1))]),i[32]||(i[32]=d(`<p>安装 Git 非常简单，打开一个命令行终端，并输入命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install git-all</span></span></code></pre></div><p>这将会安装大量依赖包，但是你将了解使用 Git 和 GitHub 所需的一切。</p><p>附注：我使用 Git 来下载程序的安装源码。有许多时候，内置的软件管理器不提供某个软件，除了去第三方库中下载源码，我经常去这个软件项目的 Git 主页，像这样克隆：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone ADDRESS</span></span></code></pre></div><p>“ADDRESS” 就是那个软件项目的 Git 主页。这样我就可以确保自己安装那个软件的最新发行版了。</p><h3 id="创建一个本地仓库并添加一个文件" tabindex="-1">创建一个本地仓库并添加一个文件 <a class="header-anchor" href="#创建一个本地仓库并添加一个文件" aria-label="Permalink to “创建一个本地仓库并添加一个文件”">​</a></h3><p>下一步就是在你的电脑里创建一个本地仓库（本文称之为 newproject，位于 <code>~/</code> 目录下），打开一个命令行终端，并输入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd ~/</span></span>
<span class="line"><span>mkdir newproject</span></span>
<span class="line"><span>cd newproject</span></span></code></pre></div><p>现在你需要初始化这个仓库。在 <code>~/newproject</code> 目录下，输入命令 <code>git init</code>，当命令运行完，你就可以看到一个刚刚创建的空的 Git 仓库了（图1）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/git_1.jpg?itok=FKkr5Mrk" alt="new repository" title="new repository"></p><p><em>图 1: 初始化完成的新仓库</em></p><p>下一步就是往项目里添加文件。我们在项目根目录（<code>~/newproject</code>）输入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>touch readme.txt</span></span></code></pre></div><p>现在项目里多了个空文件。输入 <code>git status</code> 来验证 Git 已经检测到多了个新文件（图2）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/git_2.jpg?itok=54G9KBHS" alt="readme" title="readme"></p><p><em>图 2: Git 检测到新文件readme.txt</em></p><p>即使 Git 检测到新的文件，但它并没有被真正的加入这个项目仓库。为此，你要输入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git add readme.txt</span></span></code></pre></div><p>一旦完成这个命令，再输入 <code>git status</code> 命令，可以看到，<code>readme.txt</code> 已经是这个项目里的新文件了（图3）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/git_3.jpg?itok=KAJwRJIB" alt="file added" title="file added"></p><p><em>图 3: 我们的文件已经被添加进临时环境</em></p><h3 id="第一次提交" tabindex="-1">第一次提交 <a class="header-anchor" href="#第一次提交" aria-label="Permalink to “第一次提交”">​</a></h3><p>当新文件添加进临时环境之后，我们现在就准备好创建第一个<ruby>提交<rt>commit</rt></ruby>了。什么是提交呢？简单的说，一个提交就是你更改的项目的文件的记录。创建一个提交也是非常简单的。但是，为提交包含一个描述信息非常重要。通过这样做，你可以添加有关该提交包含的内容的注释，比如你对文件做出的何种修改。然而，在这样做之前，我们需要告知 Git 我们的账户，输入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git config --global user.email EMAIL</span></span>
<span class="line"><span>git config --global user.name “FULL NAME”</span></span></code></pre></div><p>“EMAIL” 即你的 email 地址，“FULL NAME” 则是你的姓名。</p><p>现在你可以通过以下命令创建一个提交：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git commit -m “Descriptive Message”</span></span></code></pre></div><p>“Descriptive Message” 即为你的提交的描述性信息。比如，当你第一个提交是提交一个 <code>readme.txt</code> 文件，你可以这样提交：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git commit -m “First draft of readme.txt file”</span></span></code></pre></div><p>你可以看到输出表明一个文件已经修改，并且，为 <code>readme.txt</code> 创建了一个新的文件模式（图4）</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/git_4.jpg?itok=qR0ighDz" alt="success" title="success"></p><p><em>图4：提交成功</em></p><h3 id="创建分支并推送至-github" tabindex="-1">创建分支并推送至 GitHub <a class="header-anchor" href="#创建分支并推送至-github" aria-label="Permalink to “创建分支并推送至 GitHub”">​</a></h3><p>分支是很重要的，它允许你在项目状态间中移动。假如，你想给你的应用创建一个新的特性。为了这样做，你创建了个新分支。一旦你完成你的新特性，你可以把这个新分支合并到你的主分支中去，使用以下命令创建一个新分支：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git checkout -b BRANCH</span></span></code></pre></div><p>“BRANCH” 即为你新分支的名字，一旦执行完命令，输入 <code>git branch</code> 命令来查看是否创建了新分支（图5）</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/git_5.jpg?itok=6m9RTWg6" alt="featureX" title="featureX"></p><p><em>图5:名为 featureX 的新分支</em></p><p>接下来，我们需要在 GitHub 上创建一个仓库。 登录 GitHub 帐户，请单击帐户主页上的“New Repository”按钮。 填写必要的信息，然后单击 “Create repository”（图6）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/git_6.jpg?itok=d2toRrUq" alt="new repository" title="new repository"></p><p><em>图6:在 GitHub 上新建一个仓库</em></p><p>在创建完一个仓库之后，你可以看到一个用于推送本地仓库的地址。若要推送，返回命令行窗口（<code>~/newproject</code> 目录中），输入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git remote add origin URL</span></span>
<span class="line"><span>git push -u origin master</span></span></code></pre></div><p>“URL” 即为我们 GitHub 上新建的仓库地址。</p><p>系统会提示您，输入 GitHub 的用户名和密码，一旦授权成功，你的项目将会被推送到 GitHub 仓库中。</p><h3 id="拉取项目" tabindex="-1">拉取项目 <a class="header-anchor" href="#拉取项目" aria-label="Permalink to “拉取项目”">​</a></h3><p>如果你的同事改变了你们 GitHub 上项目的代码，并且已经合并那些更改，你可以拉取那些项目文件到你的本地机器，这样，你系统中的文件就可以和远程用户的文件保持匹配。你可以输入以下命令来做这件事（<code>~/newproject</code> 在目录中），</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git pull origin master</span></span></code></pre></div><p>以上的命令可以拉取任何新文件或修改过的文件到你的本地仓库。</p><h3 id="基础" tabindex="-1">基础 <a class="header-anchor" href="#基础" aria-label="Permalink to “基础”">​</a></h3><p>这就是从命令行使用 Git 来处理存储在 GitHub 上的项目的基础知识。 还有很多东西需要学习，所以我强烈建议你使用 <code>man git</code>，<code>man git-push</code> 和 <code>man git-pull</code> 命令来更深入地了解 <code>git</code> 命令可以做什么。</p><p>开发快乐！</p>`,53)),s("p",null,[i[9]||(i[9]=t("了解更多关于 Linux 的 内容，请访问来自 Linux 基金会和 edX 的免费的 ",-1)),l(e,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:a(()=>[...i[8]||(i[8]=[t('"Introduction to Linux"',-1)])]),_:1}),i[10]||(i[10]=t("课程。",-1))]),i[33]||(i[33]=s("hr",null,null,-1)),s("p",null,[i[12]||(i[12]=t("via: ",-1)),l(e,{href:"https://www.linux.com/learn/intro-to-linux/2018/7/introduction-using-git"},{default:a(()=>[...i[11]||(i[11]=[t("https://www.linux.com/learn/intro-to-linux/2018/7/introduction-using-git",-1)])]),_:1})]),s("p",null,[i[17]||(i[17]=t("作者：",-1)),l(e,{href:"https://www.linux.com/users/jlwallen"},{default:a(()=>[...i[13]||(i[13]=[t("Jack Wallen",-1)])]),_:1}),i[18]||(i[18]=t(" 选题：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...i[14]||(i[14]=[t("lujun9972",-1)])]),_:1}),i[19]||(i[19]=t(" 译者：",-1)),l(e,{href:"https://github.com/distant1219"},{default:a(()=>[...i[15]||(i[15]=[t("distant1219",-1)])]),_:1}),i[20]||(i[20]=t(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:a(()=>[...i[16]||(i[16]=[t("wxy",-1)])]),_:1})]),s("p",null,[i[23]||(i[23]=t("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[21]||(i[21]=[t("LCTT",-1)])]),_:1}),i[24]||(i[24]=t(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:a(()=>[...i[22]||(i[22]=[t("Linux中国",-1)])]),_:1}),i[25]||(i[25]=t(" 荣誉推出",-1))])])}const w=n(g,[["render",u]]);export{y as __pageData,w as default};
